#[cfg(test)]
mod generated_26_1_tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn generated_map_decorations_are_contiguous_and_unique() {
        assert_eq!(VANILLA_MAP_DECORATION_TYPES.len(), 35);
        let mut resources = HashSet::new();
        for (type_id, entry) in VANILLA_MAP_DECORATION_TYPES.iter().enumerate() {
            assert_eq!(entry.type_id, type_id as i32);
            assert!(resources.insert(entry.resource_id));
        }
    }

    #[test]
    fn production_sources_do_not_redeclare_map_decoration_catalog() {
        let renderer = include_str!("../../../bbb-renderer/src/item_models/map.rs");
        let lookup = renderer
            .split("pub fn item_frame_map_decoration_type")
            .nth(1)
            .and_then(|source| source.split("/// Bakes vanilla").next())
            .expect("map decoration lookup");
        assert_eq!(
            lookup
                .matches("vanilla_map_decoration_type(type_id)")
                .count(),
            1
        );
        let bake = renderer.split("fn bake_map_decoration_surface(").nth(1).and_then(|source| source.split("/// Bakes one item-frame-visible vanilla `MapRenderer` decoration name submit.").next()).expect("map decoration surface baker");
        assert_eq!(
            bake.matches("item_frame_map_decoration_type(type_id)?")
                .count(),
            1
        );
        assert!(bake.contains("decoration_type.render_on_frame"));
        assert!(bake.contains("decoration_type.sprite_id"));
        let fixture = renderer
            .split("fn generated_map_decoration_catalog_drives_all_surface_metadata")
            .nth(1)
            .and_then(|source| source.split_once("\n    }"))
            .map(|(body, _)| body)
            .expect("map decoration full-catalog fixture");
        assert_eq!(fixture.matches("vanilla_map_decoration_types").count(), 2);
        assert!(fixture.contains("entry.render_on_frame"));
        assert_eq!(fixture.matches("entry.sprite_id").count(), 2);
        for entry in VANILLA_MAP_DECORATION_TYPES {
            assert!(
                !fixture.contains(entry.resource_id),
                "fixture restored resource literal {}",
                entry.resource_id
            );
            assert!(
                !fixture.contains(entry.sprite_id),
                "fixture restored sprite literal {}",
                entry.sprite_id
            );
            assert!(
                !lookup.contains(entry.resource_id),
                "lookup restored resource literal {}",
                entry.resource_id
            );
            assert!(
                !bake.contains(entry.sprite_id),
                "baker restored sprite literal {}",
                entry.sprite_id
            );
        }
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/map_decorations/generated_26_1.rs")
                    || display.ends_with("/tests.rs")
                    || display.contains("/tests/")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                let production = source.split("#[cfg(test)]").next().unwrap_or(&source);
                if production.contains("const VANILLA_MAP_DECORATION_TYPES") {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "parallel map decoration catalog owners: {violations:?}"
        );
    }
}
